#include <windows.h>
#include <GL/gl.h>
#include <stdio.h>
int main(void){PIXELFORMATDESCRIPTOR p={0};HWND w;HDC dc;HGLRC c;int f;unsigned char px[4]={0};w=CreateWindowA("STATIC","WineMetalGL fixed",WS_OVERLAPPEDWINDOW,0,0,64,64,0,0,0,0);if(!w)return 11;dc=GetDC(w);p.nSize=sizeof(p);p.nVersion=1;p.dwFlags=PFD_DRAW_TO_WINDOW|PFD_SUPPORT_OPENGL;p.iPixelType=PFD_TYPE_RGBA;p.cColorBits=32;f=ChoosePixelFormat(dc,&p);if(!f||!SetPixelFormat(dc,f,&p))return 12;c=wglCreateContext(dc);if(!c||!wglMakeCurrent(dc,c))return 13;glViewport(0,0,64,64);glClearColor(0,0,0,1);glClear(GL_COLOR_BUFFER_BIT);glBegin(GL_TRIANGLES);glColor4f(0.8f,0.1f,0.05f,1);glVertex3f(-1,-1,0);glVertex3f(3,-1,0);glVertex3f(-1,3,0);glEnd();glReadPixels(32,32,1,1,GL_RGBA,GL_UNSIGNED_BYTE,px);printf("Fixed rgba=%u,%u,%u,%u error=0x%x\n",px[0],px[1],px[2],px[3],(unsigned)glGetError());if(px[0]<190||px[0]>215||px[1]<20||px[1]>35||px[2]<5||px[2]>20||px[3]<250)return 14;printf("WINEMETALGL_FIXED_OK\n");SwapBuffers(dc);wglMakeCurrent(0,0);wglDeleteContext(c);ReleaseDC(w,dc);DestroyWindow(w);return 0;}
